CREATE OR REPLACE FUNCTION public.fu_next_weekday(p_date date) RETURNS date LANGUAGE sql IMMUTABLE STRICT SET search_path=public AS $$ SELECT p_date + CASE extract(isodow FROM p_date)::int WHEN 6 THEN 2 WHEN 7 THEN 1 ELSE 0 END $$;
CREATE OR REPLACE FUNCTION public.fu_add_business_days(p_date date, p_days integer) RETURNS date LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=public AS $$ DECLARE d date := p_date; n integer := 0; BEGIN IF p_days < 0 OR p_days > 365 THEN RAISE EXCEPTION 'Invalid FU offset'; END IF; WHILE n < p_days LOOP d := d + 1; IF extract(isodow FROM d) <= 5 THEN n := n + 1; END IF; END LOOP; RETURN public.fu_next_weekday(d); END $$;
REVOKE ALL ON FUNCTION public.fu_next_weekday(date), public.fu_add_business_days(date,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fu_next_weekday(date), public.fu_add_business_days(date,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.normalize_fu_business_deadline() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE local_due timestamp; ref_day date; offset_days integer; BEGIN IF NEW.status <> 'pendente' OR NEW.data_prevista IS NULL THEN RETURN NEW; END IF; local_due := NEW.data_prevista AT TIME ZONE 'America/Recife'; IF TG_OP = 'INSERT' AND NEW.tipo IN ('D+1','D+7','D+15','D+30','M+7','M+30','G+7','G+30') AND NEW.data_referencia IS NOT NULL AND NEW.cancelado_motivo IS DISTINCT FROM 'reagendado' THEN ref_day := (NEW.data_referencia AT TIME ZONE 'America/Recife')::date; offset_days := split_part(NEW.tipo,'+',2)::integer; IF local_due::date = ref_day + offset_days THEN local_due := public.fu_add_business_days(ref_day,offset_days) + local_due::time; END IF; END IF; NEW.data_prevista := (public.fu_next_weekday(local_due::date) + local_due::time) AT TIME ZONE 'America/Recife'; RETURN NEW; END $$;
CREATE TRIGGER normalize_fu_business_deadline BEFORE INSERT OR UPDATE OF data_prevista,status ON public.follow_ups FOR EACH ROW EXECUTE FUNCTION public.normalize_fu_business_deadline();